body.query:
query PrActivityQuery($owner: String!, $name: String!, $number: Int!) {
  repository(owner: $owner, name: $name) {
    pullRequest(number: $number) {
      id
      comments {
        totalCount
      }
      timelineItems(last: 100, itemTypes: [ISSUE_COMMENT, PULL_REQUEST_REVIEW, PULL_REQUEST_COMMIT, CLOSED_EVENT, REOPENED_EVENT, MERGED_EVENT, CROSS_REFERENCED_EVENT, REFERENCED_EVENT, LABELED_EVENT, UNLABELED_EVENT, ASSIGNED_EVENT, UNASSIGNED_EVENT, MILESTONED_EVENT, DEMILESTONED_EVENT, ADDED_TO_PROJECT_V2_EVENT, REMOVED_FROM_PROJECT_V2_EVENT, PROJECT_V2_ITEM_STATUS_CHANGED_EVENT, REVIEW_REQUESTED_EVENT, REVIEW_REQUEST_REMOVED_EVENT, REVIEW_DISMISSED_EVENT, RENAMED_TITLE_EVENT, READY_FOR_REVIEW_EVENT, CONVERT_TO_DRAFT_EVENT, HEAD_REF_FORCE_PUSHED_EVENT, BASE_REF_FORCE_PUSHED_EVENT, HEAD_REF_DELETED_EVENT, HEAD_REF_RESTORED_EVENT, BASE_REF_CHANGED_EVENT, LOCKED_EVENT, UNLOCKED_EVENT, MARKED_AS_DUPLICATE_EVENT, UNMARKED_AS_DUPLICATE_EVENT, AUTO_MERGE_ENABLED_EVENT, AUTO_MERGE_DISABLED_EVENT, ADDED_TO_MERGE_QUEUE_EVENT, REMOVED_FROM_MERGE_QUEUE_EVENT]) {
        totalCount
        nodes {
          __typename
          ... on IssueComment {
            id
            fullDatabaseId
            author {
              login
            }
            body
            createdAt
            viewerCanUpdate
            viewerCanDelete
            viewerCanReact
            reactionGroups {
              content
              viewerHasReacted
              reactors {
                totalCount
              }
            }
            isMinimized
            minimizedReason
            viewerCanMinimize
            viewerCanUnminimize
          }
          ... on PullRequestReview {
            id
            fullDatabaseId
            author {
              login
            }
            state
            body
            submittedAt
            createdAt
            commit {
              oid
            }
            comments(first: 0) {
              totalCount
            }
            viewerCanUpdate
            viewerCanDelete
            viewerCanReact
            reactionGroups {
              content
              viewerHasReacted
              reactors {
                totalCount
              }
            }
          }
          ... on PullRequestCommit {
            commit {
              oid
              message
              committedDate
              author {
                name
                user {
                  login
                }
              }
            }
          }
          ... on ClosedEvent {
            actor {
              login
            }
            createdAt
            closer {
              __typename
              ... on Commit {
                oid
              }
              ... on PullRequest {
                number
                title
                __typename
                ... {
                  isDraft
                  state
                }
                repository {
                  nameWithOwner
                }
              }
            }
            stateReason
          }
          ... on ReopenedEvent {
            actor {
              login
            }
            createdAt
          }
          ... on MergedEvent {
            actor {
              login
            }
            createdAt
            commit {
              oid
            }
            mergeRefName
          }
          ... on CrossReferencedEvent {
            actor {
              login
            }
            createdAt
            source {
              __typename
              ... on Issue {
                number
                title
                state
                stateReason
                repository {
                  nameWithOwner
                }
              }
              ... on PullRequest {
                number
                title
                __typename
                ... {
                  isDraft
                  state
                }
                repository {
                  nameWithOwner
                }
              }
            }
            willCloseTarget
          }
          ... on ReferencedEvent {
            actor {
              login
            }
            createdAt
            commit {
              oid
            }
            commitRepository {
              nameWithOwner
            }
          }
          ... on LabeledEvent {
            actor {
              login
            }
            createdAt
            label {
              name
              color
            }
          }
          ... on UnlabeledEvent {
            actor {
              login
            }
            createdAt
            label {
              name
              color
            }
          }
          ... on AssignedEvent {
            actor {
              login
            }
            createdAt
            assignee {
              __typename
              ... on User {
                login
              }
              ... on Bot {
                login
              }
            }
          }
          ... on UnassignedEvent {
            actor {
              login
            }
            createdAt
            assignee {
              __typename
              ... on User {
                login
              }
              ... on Bot {
                login
              }
            }
          }
          ... on MilestonedEvent {
            actor {
              login
            }
            createdAt
            milestoneTitle
          }
          ... on DemilestonedEvent {
            actor {
              login
            }
            createdAt
            milestoneTitle
          }
          ... on AddedToProjectV2Event {
            actor {
              login
            }
            createdAt
          }
          ... on RemovedFromProjectV2Event {
            actor {
              login
            }
            createdAt
          }
          ... on ProjectV2ItemStatusChangedEvent {
            actor {
              login
            }
            createdAt
            previousStatus
            status
          }
          ... on ReviewRequestedEvent {
            actor {
              login
            }
            createdAt
            requestedReviewer {
              __typename
              ... on User {
                login
              }
              ... on Bot {
                login
              }
              ... on Team {
                combinedSlug
              }
            }
          }
          ... on ReviewRequestRemovedEvent {
            actor {
              login
            }
            createdAt
            requestedReviewer {
              __typename
              ... on User {
                login
              }
              ... on Bot {
                login
              }
              ... on Team {
                combinedSlug
              }
            }
          }
          ... on ReviewDismissedEvent {
            actor {
              login
            }
            createdAt
            dismissalMessage
            review {
              author {
                login
              }
            }
          }
          ... on RenamedTitleEvent {
            actor {
              login
            }
            createdAt
            previousTitle
            currentTitle
          }
          ... on ReadyForReviewEvent {
            actor {
              login
            }
            createdAt
          }
          ... on ConvertToDraftEvent {
            actor {
              login
            }
            createdAt
          }
          ... on HeadRefForcePushedEvent {
            actor {
              login
            }
            createdAt
            beforeCommit {
              oid
            }
            afterCommit {
              oid
            }
          }
          ... on BaseRefForcePushedEvent {
            actor {
              login
            }
            createdAt
            beforeCommit {
              oid
            }
            afterCommit {
              oid
            }
          }
          ... on HeadRefDeletedEvent {
            actor {
              login
            }
            createdAt
            headRefName
          }
          ... on HeadRefRestoredEvent {
            actor {
              login
            }
            createdAt
          }
          ... on BaseRefChangedEvent {
            actor {
              login
            }
            createdAt
            previousRefName
            currentRefName
          }
          ... on LockedEvent {
            actor {
              login
            }
            createdAt
            lockReason
          }
          ... on UnlockedEvent {
            actor {
              login
            }
            createdAt
          }
          ... on MarkedAsDuplicateEvent {
            actor {
              login
            }
            createdAt
            canonical {
              __typename
              ... on Issue {
                number
                title
                state
                stateReason
                repository {
                  nameWithOwner
                }
              }
              ... on PullRequest {
                number
                title
                __typename
                ... {
                  isDraft
                  state
                }
                repository {
                  nameWithOwner
                }
              }
            }
          }
          ... on UnmarkedAsDuplicateEvent {
            actor {
              login
            }
            createdAt
            canonical {
              __typename
              ... on Issue {
                number
                title
                state
                stateReason
                repository {
                  nameWithOwner
                }
              }
              ... on PullRequest {
                number
                title
                __typename
                ... {
                  isDraft
                  state
                }
                repository {
                  nameWithOwner
                }
              }
            }
          }
          ... on AutoMergeEnabledEvent {
            actor {
              login
            }
            createdAt
          }
          ... on AutoMergeDisabledEvent {
            actor {
              login
            }
            createdAt
          }
          ... on AddedToMergeQueueEvent {
            actor {
              login
            }
            createdAt
          }
          ... on RemovedFromMergeQueueEvent {
            actor {
              login
            }
            createdAt
            reason
          }
        }
      }
      commits(last: 100) {
        totalCount
        nodes {
          commit {
            oid
            message
            committedDate
            author {
              name
              user {
                login
              }
            }
          }
        }
      }
      reviewRequests(first: 100) {
        totalCount
        nodes {
          asCodeOwner
          requestedReviewer {
            __typename
            ... on User {
              login
            }
            ... on Bot {
              login
            }
            ... on Team {
              combinedSlug
            }
          }
        }
      }
      latestReviews(first: 100) {
        totalCount
        nodes {
          fullDatabaseId
          author {
            login
          }
          state
          submittedAt
          commit {
            oid
          }
          onBehalfOf(first: 10) {
            totalCount
            nodes {
              combinedSlug
            }
          }
        }
      }
      closingIssuesReferences(first: 10) {
        totalCount
        nodes {
          number
          title
          state
          stateReason
          repository {
            nameWithOwner
          }
        }
      }
      mergeCommit {
        oid
      }
      pending_review: reviews(first: 1, states: [PENDING]) {
        totalCount
        nodes {
          id
          fullDatabaseId
          author {
            login
          }
          state
          body
          submittedAt
          createdAt
          commit {
            oid
          }
          comments(first: 0) {
            totalCount
          }
          viewerCanUpdate
          viewerCanDelete
          viewerCanReact
          reactionGroups {
            content
            viewerHasReacted
            reactors {
              totalCount
            }
          }
        }
      }
    }
  }
}
